@[ext]
theorem IncidenceClosedSet.ext {A B : Type*} {inc : A → B → Prop}
    {X Y : IncidenceClosedSet inc} (h : (X : Set B) = Y) : X = Y

theorem coPointedDefect_eq_pointedDefect_add {X : PointedFaceState}
    (hX : X.WellFormed) :
    X.coPointedDefect = X.pointedDefect + 3 * (X.p - X.q)

theorem join_admissible {A B : PointedFaceState}
    (hA : A.Admissible) (hB : B.Admissible) :
    (A.join B).Admissible

theorem join_coPointedDefect_nonneg {A B : PointedFaceState}
    (hA : A.Admissible) (hB : B.Admissible) :
    0 ≤ (A.join B).coPointedDefect

theorem join_coPointedDefect_pos {A B : PointedFaceState}
    (hA : A.StronglyAdmissible) (hB : B.StronglyAdmissible) :
    0 < (A.join B).coPointedDefect

theorem join_stronglyAdmissible {A B : PointedFaceState}
    (hA : A.StronglyAdmissible) (hB : B.StronglyAdmissible) :
    (A.join B).StronglyAdmissible

theorem join_wellFormed {A B : PointedFaceState}
    (hA : A.WellFormed) (hB : B.WellFormed) :
    (A.join B).WellFormed

theorem union_admissible {A B : PointedFaceState}
    (hA : A.Admissible) (hB : B.Admissible) :
    (A.union B).Admissible

theorem union_pointedDefect_pos {A B : PointedFaceState}
    (hA : A.StronglyAdmissible) (hB : B.StronglyAdmissible) :
    0 < (A.union B).pointedDefect

theorem union_stronglyAdmissible {A B : PointedFaceState}
    (hA : A.StronglyAdmissible) (hB : B.StronglyAdmissible) :
    (A.union B).StronglyAdmissible

theorem union_wellFormed {A B : PointedFaceState}
    (hA : A.WellFormed) (hB : B.WellFormed) :
    (A.union B).WellFormed

theorem toFlag_toRankedFlagOfCardEq (s : Flag P) {n : ℕ}
    (hcard : Nat.card s = n + 1) :
    (toRankedFlagOfCardEq s hcard).toFlag = s

@[ext] theorem ShufflePath.ext {n m : ℕ} {s t : ShufflePath n m}
    (hleft : ∀ k, s.left k = t.left k)
    (hright : ∀ k, s.right k = t.right k) : s = t

theorem covBy_switchMiddle_succ {N : ℕ}
    (f : RankedFlag P (N + 1)) (i : Fin N) :
    f (switchMiddleIndex i) ⋖ f (switchSuccIndex i)

theorem covBy_switchPred_middle {N : ℕ}
    (f : RankedFlag P (N + 1)) (i : Fin N) :
    f (switchPredIndex i) ⋖ f (switchMiddleIndex i)

lemma Tengoku.MahlerHansenCograph.lintegral_fix_eq_lmarginal {d : ℕ}
    (F : (Fin (d + 2) → ℝ) → ENNReal) (x1 : Fin (d + 1) → ℝ)
    : ∫⁻ y : Fin 1 → ℝ, (fix F x1) y = (∫⋯∫⁻_{⟨d+1, by simp⟩}, F) (append x1 default)

lemma volume_eq_lintegral_fiber_of_nullMeasurableSet
    {V : Type u} {W : Type v} [Fintype V] [Fintype W]
    {J : Set ((V → ℝ) × (W → ℝ))}
    (hJ : NullMeasurableSet J volume) :
    volume J =
      ∫⁻ x : V → ℝ, volume {y : W → ℝ | (x, y) ∈ J}
